package com.aoo.bcg.common.repair;
import java.util.concurrent.atomic.AtomicLong;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class VersionedRepairGuardTest{@Test void staleRepairCannotOverwriteConcurrentBusinessWrite()throws Exception{var guard=new VersionedRepairGuard();var version=new AtomicLong(8);var request=new VersionedRepairGuard.Request("repair-1","club","42",7);var conflict=assertThrows(VersionedRepairGuard.StaleRepairException.class,()->guard.execute(request,version::get,current->version.incrementAndGet()));assertEquals(8,conflict.actual());assertEquals(8,version.get());var accepted=guard.execute(new VersionedRepairGuard.Request("repair-2","club","42",8),version::get,current->version.incrementAndGet());assertEquals(8,accepted.beforeVersion());assertEquals(9,accepted.afterVersion());}}
